    rw_cells asegs mm (SP + 120) [C8 (Z_to_bv 64 (OP1 - DL)); C8 (Z_to_bv 64 (OP0 - DL)); C8 (Z_to_bv 64 2147450880)] ->
    rw_cells asegs mm (SP + 224) [C8 (Z_to_bv 64 0x20dc4); C8 (Z_to_bv 64 DL)] ->
    stk asegs mm (SP + 144) (SP + 224) -> wr_at asegs mm (SP + 144) 96 ->
